t.script:
(function(){
  var pop = document.getElementById('pcPop');
  var curId = null, curMois = 0, curVehId = null, curAttelId = null, curAttelName = '';
  function rpc(model, method, args, kwargs){
    return fetch('/web/dataset/call_kw', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{model:model, method:method, args:args, kwargs:kwargs || {}}})
    }).then(function(r){ return r.json(); }).then(function(d){
      if(d.error){ throw new Error(d.error.data && d.error.data.message || d.error.message); }
      return d.result;
    });
  }
  function loadDocs(){
    var box = document.getElementById('pcDocList');
    box.textContent = 'Chargement…';
    var ids = [parseInt(curVehId,10)];
    if(curAttelId){ ids.push(parseInt(curAttelId,10)); }
    document.getElementById('pcDocTitle').textContent = curAttelId ? ('📎 Documents de l\'attelage complet (véhicule + ' + curAttelName + ')') : '📎 Documents du véhicule';
    rpc('ir.attachment', 'search_read', [[['res_model','=','fleet.vehicle'],['res_id','in',ids]]], {fields:['id','name','res_id'], order:'id desc', limit:25}).then(function(res){
      box.textContent = '';
      if(!res.length){ box.textContent = 'Aucun document.'; return; }
      res.forEach(function(a){
        var d = document.createElement('div');
        var link = document.createElement('a');
        link.href = '/web/content/' + a.id + '?download=true';
        link.target = '_blank';
        link.style.cssText = 'color:#0f172a;font-weight:700;';
        link.textContent = a.name;
        d.appendChild(document.createTextNode('📄 '));
        d.appendChild(link);
        if(curAttelId && a.res_id === parseInt(curAttelId,10)){
          var tag = document.createElement('span');
          tag.style.cssText = 'color:#1e40af;font-weight:800;font-size:11px;margin-left:6px;background:#eff6ff;border-radius:6px;padding:1px 6px;';
          tag.textContent = '🔗 ' + curAttelName;
          d.appendChild(tag);
        }
        box.appendChild(d);
      });
    }).catch(function(){ box.textContent = 'Erreur de chargement.'; });
  }
  function nextEch(dateVal){
    if(!dateVal || !curMois){ return ''; }
    var d = new Date(dateVal + 'T00:00:00');
    d.setDate(d.getDate() + 30 * curMois);
    return d.toLocaleDateString('fr-FR');
  }
  function refreshNext(){
    var dv = document.getElementById('pcPopDate').value;
    var n = nextEch(dv);
    document.getElementById('pcPopNext').textContent = n ? ('Prochain contrôle planifié automatiquement autour du ' + n) : '';
  }
  function openPop(btn){
    curId = btn.getAttribute('data-id');
    curVehId = btn.getAttribute('data-vehid');
    curAttelId = btn.getAttribute('data-attelid') || null;
    curAttelName = btn.getAttribute('data-attelname') || '';
    curMois = parseInt(btn.getAttribute('data-mois'), 10) || 0;
    document.getElementById('pcPopVeh').textContent = btn.getAttribute('data-veh');
    document.getElementById('pcPopType').textContent = btn.getAttribute('data-type') + ' — périodicité ' + btn.getAttribute('data-mois') + ' mois';
    document.getElementById('pcPopDate').value = btn.getAttribute('data-date') || '';
    var cbb = btn.getAttribute('data-combo') || '';
    document.getElementById('pcComboZone').style.display = cbb ? 'flex' : 'none';
    document.getElementById('pcComboName').textContent = cbb;
    var cv = btn.getAttribute('data-cv') || '';
    var t = new Date();
    if(cv){
      document.getElementById('pcCvPending').style.display = 'block';
      document.getElementById('pcCvSet').style.display = 'none';
      document.getElementById('pcCvLim').textContent = cv.split('-').reverse().join('/');
      document.getElementById('pcCvDoneDate').value = t.getFullYear() + '-' + String(t.getMonth()+1).padStart(2,'0') + '-' + String(t.getDate()).padStart(2,'0');
    } else {
      document.getElementById('pcCvPending').style.display = 'none';
      document.getElementById('pcCvSet').style.display = 'block';
      var lim = new Date(t); lim.setMonth(lim.getMonth() + 2);
      document.getElementById('pcCvLimite').value = lim.getFullYear() + '-' + String(lim.getMonth()+1).padStart(2,'0') + '-' + String(lim.getDate()).padStart(2,'0');
    }
    loadDocs();
    refreshNext();
    pop.classList.add('show');
  }
  function closePop(){ pop.classList.remove('show'); curId = null; curMois = 0; curVehId = null; }
  document.querySelectorAll('.pc-cell, .pc-ev[data-id]').forEach(function(b){ b.addEventListener('click', function(){ openPop(b); }); });
  document.getElementById('pcPopCancel').addEventListener('click', closePop);
  document.getElementById('pcPopDate').addEventListener('change', refreshNext);
  pop.addEventListener('click', function(e){ if(e.target === pop){ closePop(); } });
  function save(dateVal){
    if(!curId){ return; }
    fetch('/web/dataset/call_kw', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{model:'ir.actions.server', method:'run', args:[[2055]], kwargs:{context:{active_model:'x_controle_vehicule', pc_id:curId, pc_date:dateVal || '', pc_combo_too:(dateVal && document.getElementById('pcComboZone').style.display !== 'none' && document.getElementById('pcComboChk').checked) ? 1 : 0}}}})
    }).then(function(r){return r.json();}).then(function(d){
      if(d.error){ alert('Échec : ' + (d.error.data && d.error.data.message || d.error.message)); return; }
      location.reload();
    }).catch(function(){ alert('Échec réseau'); });
  }
  document.getElementById('pcPopSave').addEventListener('click', function(){ save(document.getElementById('pcPopDate').value); });
  document.getElementById('pcPopValid').addEventListener('click', function(){
    var t = new Date();
    var iso = t.getFullYear() + '-' + String(t.getMonth()+1).padStart(2,'0') + '-' + String(t.getDate()).padStart(2,'0');
    save(iso);
  });
  document.getElementById('pcPopClear').addEventListener('click', function(){ if(confirm('Effacer la date de ce contrôle ?\n(la ligne d\'historique déjà créée dans l\'onglet Services du véhicule ne sera pas supprimée, et le prochain contrôle planifié automatiquement sera annulé)')){ save(''); } });
  function runCtx(ctx){
    ctx.active_model = 'x_controle_vehicule';
    ctx.pc_id = curId;
    rpc('ir.actions.server', 'run', [[2055]], {context: ctx}).then(function(){ location.reload(); })
      .catch(function(e){ alert('Échec : ' + e.message); });
  }
  document.getElementById('pcCvSetBtn').addEventListener('click', function(){
    var lim = document.getElementById('pcCvLimite').value;
    if(!lim){ alert('Choisissez la date limite de la contre-visite.'); return; }
    runCtx({pc_cv_limite: lim});
  });
  document.getElementById('pcCvDoneBtn').addEventListener('click', function(){
    runCtx({pc_cv_done: 1, pc_date: document.getElementById('pcCvDoneDate').value || ''});
  });
  document.getElementById('pcDocUp').addEventListener('click', function(){
    var f = document.getElementById('pcDocFile').files[0];
    if(!f){ alert('Choisissez un fichier.'); return; }
    if(f.size > 20 * 1024 * 1024){ alert('Fichier trop volumineux (20 Mo max).'); return; }
    var reader = new FileReader();
    reader.onload = function(){
      var b64 = reader.result.split(',')[1];
      rpc('ir.attachment', 'create', [{
        name: f.name,
        datas: b64,
        res_model: 'fleet.vehicle',
        res_id: parseInt(curVehId, 10),
      }]).then(function(){ document.getElementById('pcDocFile').value = ''; loadDocs(); })
        .catch(function(e){ alert('Échec de l\'envoi : ' + e.message); });
    };
    reader.readAsDataURL(f);
  });
  function pcNav(params){
    var q = new URLSearchParams(location.search);
    Object.keys(params).forEach(function(k){ q.set(k, params[k]); });
    location = '/parc-controles?' + q.toString();
  }
  var semPick = document.getElementById('pcSem');
  if(semPick){ semPick.addEventListener('change', function(){ if(semPick.value){ pcNav({vue:'semaine', sem:semPick.value}); } }); }
  var moisPick = document.getElementById('pcMois');
  if(moisPick){ moisPick.addEventListener('change', function(){ if(moisPick.value){ pcNav({vue:'mois', mois:moisPick.value}); } }); }
  var attVeh = null;
  document.querySelectorAll('.pc-att').forEach(function(b){
    b.addEventListener('click', function(ev){
      ev.stopPropagation();
      attVeh = b.getAttribute('data-veh');
      document.getElementById('pcAttTitle').textContent = '🚛🔗 Attelage — ' + b.getAttribute('data-vname');
      var src = (b.getAttribute('data-cat') === 'remorque') ? 'pcAttSrcTrac' : 'pcAttSrcRem';
      var sel = document.getElementById('pcAttSel');
      sel.innerHTML = '';
      var none = document.createElement('option');
      none.value = '';
      none.textContent = '— aucun —';
      sel.appendChild(none);
      document.getElementById(src).querySelectorAll('option').forEach(function(o){ sel.appendChild(o.cloneNode(true)); });
      sel.value = b.getAttribute('data-cur') || '';
      document.getElementById('pcAttPop').classList.add('show');
    });
  });
  document.getElementById('pcAttCancel').addEventListener('click', function(){ document.getElementById('pcAttPop').classList.remove('show'); });
  document.getElementById('pcAttPop').addEventListener('click', function(e){ if(e.target === document.getElementById('pcAttPop')){ document.getElementById('pcAttPop').classList.remove('show'); } });
  document.getElementById('pcAttSave').addEventListener('click', function(){
    fetch('/web/dataset/call_kw', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{model:'ir.actions.server', method:'run', args:[[2072]], kwargs:{context:{active_model:'x_controle_vehicule', pc_veh:parseInt(attVeh,10), pc_combo:parseInt(document.getElementById('pcAttSel').value || '0', 10)}}}})
    }).then(function(r){return r.json();}).then(function(d){
      if(d.error){ alert('Échec : ' + (d.error.data && d.error.data.message || d.error.message)); return; }
      location.reload();
    }).catch(function(){ alert('Échec réseau'); });
  });
  var emSave = document.getElementById('pcEmailsSave');
  if(emSave){ emSave.addEventListener('click', function(){
    fetch('/web/dataset/call_kw', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{model:'ir.actions.server', method:'run', args:[[2056]], kwargs:{context:{active_model:'x_controle_vehicule', pc_emails:document.getElementById('pcEmails').value}}}})
    }).then(function(r){return r.json();}).then(function(d){
      if(d.error){ alert('Échec : ' + (d.error.data && d.error.data.message || d.error.message)); return; }
      emSave.textContent = '✓ Enregistré';
      setTimeout(function(){ emSave.textContent = 'Enregistrer'; }, 2000);
    }).catch(function(){ alert('Échec réseau'); });
  }); }
})();
